def check(world, calls, reference=None):
    if not any(c.ok and c.name in ("search_documents", "search_files") for c in calls):
        return "not done: the corpus was never searched"
    if any(c.ok and c.name == "create_knowledge_request" for c in calls):
        return "done wrong: a knowledge request was opened that the employee did not ask for"
    missing = _evidence_missing(world, calls, reference)
    if missing:
        return f"done blind: the answer rests on {', '.join(missing)}, which was never read"
    return _unasked_write(world, reference)


