def check(world, calls, reference=None):
    fid = None
    for step in reference or ():
        if step.get("tool") == "get_document_owner":
            fid = step.get("arguments", {}).get("drive_file_id") or fid
    state = world.state()
    owner_of = {d["drive_file_id"]: d["owner_id"] for d in state.get("kb_documents", [])}
    email_of = {e["employee_id"]: e["email"] for e in state.get("employees", [])}
    issues = {i["issue_id"]: i for i in state.get("document_issues", [])}

    def owner_returned(c, target):
        """Whether this call returned `target`'s owner: the owner tool, the document's metadata,
        its Drive metadata (or a Drive search or listing that carries it), or an issue raised on it
        (which names the owner it was routed to)."""
        r = c.result if isinstance(c.result, dict) else {}
        owner = owner_of.get(target)
        if owner is None:
            return False
        if c.name in ("get_document_owner", "get_document_metadata") and c.arguments.get("drive_file_id") == target:
            return r.get("owner_id") == owner
        if c.name == "flag_document_issue" and c.arguments.get("drive_file_id") == target:
            issue = issues.get(r.get("issue_id"))
            return r.get("owner_id") == owner and issue is not None and issue["owner_id"] == owner
        if c.name == "get_file_metadata" and c.arguments.get("fileId") == target:
            return bool(r.get("owner")) and r.get("owner") == email_of.get(owner)
        # A Drive search or recent-files listing returns each file's owner, as its metadata does.
        if c.name in ("search_files", "list_recent_files"):
            return any(f.get("id") == target and f.get("owner") and f.get("owner") == email_of.get(owner) for f in r.get("files") or [])
        return False

    ok = [c for c in calls if c.ok]
    if fid:
        # The team directory names team leads and collection owners, not who owns this document.
        if not any(owner_returned(c, fid) for c in ok):
            return f"not done: the owner of {fid} was never returned"
        return None
    if not any(c.name == "get_team_directory" or any(owner_returned(c, t) for t in owner_of) for c in ok):
        return "not done: no owner was looked up"
    return None

def check(world, calls, reference=None):
    wanted, documents, collections = [], [], False
    for step in reference or ():
        a = step.get("arguments", {})
        if step.get("tool") in ("get_user_profile", "check_document_access", "list_collections"):
            eid = a.get("employee_id")
            if eid and eid not in wanted:
                wanted.append(eid)
        if step.get("tool") == "check_document_access" and a.get("drive_file_id"):
            documents.append((a.get("employee_id"), a["drive_file_id"]))
        if step.get("tool") == "list_collections":
            collections = True
    # Only a lookup that returned the employee's role or access counts: a refused one shows nothing.
    looks = [c for c in calls if c.ok and c.name in ("get_user_profile", "check_document_access", "list_collections")]
    if not looks:
        return "not done: the employee's access was never checked"
    for eid in wanted:
        if not any(c.arguments.get("employee_id") == eid for c in looks):
            return f"done wrong: the access of {eid} was never checked"
    # When the answer turns on one document, the role alone does not say which collection that
    # document is in: its access check counts, and so does a read of it the knowledge tools refused
    # for the employee's role, which shows the same thing.
    for eid, fid in documents:
        if not any(_access_shown(world, c, fid, eid) for c in calls):
            return f"not done: whether the employee may read {fid} was never checked"
    # Which collections the employee may browse is the collection list, not the profile's ids.
    if collections and not any(c.ok and c.name == "list_collections" for c in calls):
        return "not done: the collections the employee may read were never listed"
    return None


def _access_shown(world, c, fid, eid):
    if eid and c.arguments.get("employee_id") not in (None, eid):
        return False
    if c.name == "check_document_access" and c.arguments.get("drive_file_id") == fid:
        return c.ok
    if c.ok or "not available to this employee's role" not in (c.error or ""):
        return False
    if c.name in ("get_document_metadata", "get_document_owner", "flag_document_issue") and c.arguments.get("drive_file_id") == fid:
        return True
    if c.name == "fetch_passage":
        return any(p["passage_id"] == c.arguments.get("passage_id") and p["drive_file_id"] == fid for p in world.state().get("kb_passages", []))
    return False

def check(world, calls, reference=None):
